	SetModelStatus(context.Context, *MsgSetModelStatus) (*MsgSetModelStatusResponse, error)
	// SetProfileStatus applies one governance profile status transition.
	SetProfileStatus(context.Context, *MsgSetProfileStatus) (*MsgSetProfileStatusResponse, error)
	// StakeService registers a Cortex service or tops up its bond.
	StakeService(context.Context, *MsgStakeService) (*MsgStakeServiceResponse, error)
	// BeginServiceUnstake opens one service unbonding entry.
	BeginServiceUnstake(context.Context, *MsgBeginServiceUnstake) (*MsgBeginServiceUnstakeResponse, error)
	// WithdrawServiceUnbonded withdraws matured service unbondings.
	WithdrawServiceUnbonded(context.Context, *MsgWithdrawServiceUnbonded) (*MsgWithdrawServiceUnbondedResponse, error)
	// DeclareModelSupport declares one operator/profile support row.
	DeclareModelSupport(context.Context, *MsgDeclareModelSupport) (*MsgDeclareModelSupportResponse, error)
	// BatchConfirmModelSupport refreshes support rows in one atomic batch.
	BatchConfirmModelSupport(context.Context, *MsgBatchConfirmModelSupport) (*MsgBatchConfirmModelSupportResponse, error)
	// SubmitFreezeSignal is the permissionless freeze-risk trigger.
	SubmitFreezeSignal(context.Context, *MsgSubmitFreezeSignal) (*MsgSubmitFreezeSignalResponse, error)
	// EmergencyFreezeVote records one validator ballot.
	EmergencyFreezeVote(context.Context, *MsgEmergencyFreezeVote) (*MsgEmergencyFreezeVoteResponse, error)
	// UpdateTimeoutBucket moved here from task.v1.Msg: this contract names the Hub governance handler the only writer of parameter bucket
	// versions, and x/task only reference-counts them.
	// UpdateTimeoutBucket executes the UpdateTimeoutBucket operation.
	UpdateTimeoutBucket(context.Context, *MsgUpdateTimeoutBucket) (*MsgUpdateTimeoutBucketResponse, error)
